   186  static inline uint32_t fnv_32a_buf(const void *buf, size_t len, uint32_t hval)
   187  {
   188      const uint8_t *bp = buf;
   189      size_t n = (len + 3) / 4;
   190
   191      switch (len % 4) {
   192      case 0: do { hval ^= *bp++; hval *= FNV1_32A_PRIME; //-fallthrough
   193      case 3:      hval ^= *bp++; hval *= FNV1_32A_PRIME; //-fallthrough
   194      case 2:      hval ^= *bp++; hval *= FNV1_32A_PRIME; //-fallthrough
   195      case 1:      hval ^= *bp++; hval *= FNV1_32A_PRIME;
   196                 } while (--n > 0);
   197      }
   198
   199      return hval;
   200  }
