   101  // composite cache
   102  static uint32_t composite_hash(void *key, uint32_t hval)
   103  {
   104      CompositeHashKey *k = key;
   105      hval = filter_hash(&k->filter, hval);
   106      for (size_t i = 0; i < k->bitmap_count; i++)
   107          hval = bitmap_ref_hash(&k->bitmaps[i], hval);
   108      return hval;
   109  }
   110
   111  static bool composite_compare(void *a, void *b)
   112  {
   113      CompositeHashKey *ak = a;
   114      CompositeHashKey *bk = b;
   115      if (!filter_compare(&ak->filter, &bk->filter))
   116          return false;
   117      if (ak->bitmap_count != bk->bitmap_count)
   118          return false;
   119      for (size_t i = 0; i < ak->bitmap_count; i++)
   120          if (!bitmap_ref_compare(&ak->bitmaps[i], &bk->bitmaps[i]))
   121              return false;
   122      return true;
   123  }
