   125  static bool composite_key_move(void *dst, void *src)
   126  {
   127      CompositeHashKey *d = dst, *s = src;
   128      if (d) {
   129          *d = *s;
   130          return true;
   131      }
   132
   133      for (size_t i = 0; i < s->bitmap_count; i++) {
   134          ass_cache_dec_ref(s->bitmaps[i].bm);
   135          ass_cache_dec_ref(s->bitmaps[i].bm_o);
   136      }
   137      free(s->bitmaps);
   138      return true;
   139  }
