   168  // outline cache
   169  static uint32_t outline_hash(void *key, uint32_t hval)
   170  {
   171      OutlineHashKey *k = key;
   172      switch (k->type) {
   173      case OUTLINE_GLYPH:
   174          return glyph_hash(&k->u, hval);
   175      case OUTLINE_DRAWING:
   176          return drawing_hash(&k->u, hval);
   177      case OUTLINE_BORDER:
   178          return border_hash(&k->u, hval);
   179      default:  // OUTLINE_BOX
   180          return hval;
   181      }
   182  }
