   184  static bool outline_compare(void *a, void *b)
   185  {
   186      OutlineHashKey *ak = a;
   187      OutlineHashKey *bk = b;
   188      if (ak->type != bk->type)
   189          return false;
   190      switch (ak->type) {
   191      case OUTLINE_GLYPH:
   192          return glyph_compare(&ak->u, &bk->u);
   193      case OUTLINE_DRAWING:
   194          return drawing_compare(&ak->u, &bk->u);
   195      case OUTLINE_BORDER:
   196          return border_compare(&ak->u, &bk->u);
   197      default:  // OUTLINE_BOX
   198          return true;
   199      }
   200  }
