   202  static bool outline_key_move(void *dst, void *src)
   203  {
   204      OutlineHashKey *d = dst, *s = src;
   205      if (!d) {
   206          if (s->type == OUTLINE_GLYPH)
   207              ass_cache_dec_ref(s->u.glyph.font);
   208          return true;
   209      }
   210
   211      *d = *s;
   212      if (s->type == OUTLINE_DRAWING) {
   213          d->u.drawing.text.str = ass_copy_string(s->u.drawing.text);
   214          return d->u.drawing.text.str;
   215      }
   216      if (s->type == OUTLINE_BORDER)
   217          ass_cache_inc_ref(s->u.border.outline);
   218      return true;
   219  }
